import{_ as t,o as e,a as i,b as o}from"./app.C41L12d5.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"数据搬运导览","link":"/api/SIMD-API/basic_api/data_move_guide/data_move_guide"},{"text":"概览","link":"/api/SIMD-API/basic_api/data_move_guide/overview/overview"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/data_move_guide/overview/overview.md","filePath":"api/SIMD-API/basic_api/data_move_guide/overview/overview.md","lastUpdated":1787050286000}'),r={name:"api/SIMD-API/basic_api/data_move_guide/overview/overview.md"};function s(p,a,l,n,_,d){return e(),i("div",null,[...a[0]||(a[0]=[o('<div><article class="markdown-body"><h1>概览<span id="ZH-CN_TOPIC_0000002565807407"></span></h1><p>数据搬运是算子开发中最基础且最关键的操作之一。在昇腾AI Core的分层存储架构中，数据需要在不同层级的存储单元之间流转，才能完成计算任务。数据搬运类API（DataCopy、DataCopyPad、Copy、LoadData（2D矩阵搬运）、LoadData（卷积数据搬运）、FixPipe等）开放了底层硬件搬运单元（MTE1/MTE2/MTE3/FixPipe）的能力，使开发者可以高效、灵活地在<a href="../../../basic_api/data_structures/GlobalTensor/GlobalTensor_intro.html">Global Memory</a>与各级<a href="../../../basic_api/data_structures/LocalTensor/LocalTensor_intro.html">Local Memory</a>之间，以及Local Memory内部进行数据传输。</p><p>本章节为数据搬运的导览性内容，旨在帮助读者在深入阅读后续各通路详解章节之前，建立起对以下核心概念的统一认知：</p><ul><li><p><strong>存储层级与数据通路：</strong> AI Core内部的物理存储单元有哪些，数据可以在哪些通路之间流动，以及搬运所依赖的硬件流水类型。</p></li><li><p><strong>逻辑位置（TPosition）与物理内存的映射：</strong> Ascend C通过TPosition机制隐藏硬件差异，开发者需理解VECIN/VECOUT/A1/B1/CO1等逻辑位置对应的实际物理存储。</p></li><li><p><strong>搬运功能分类：</strong> 基础数据搬运、高维切分搬运、切片搬运、随路格式转换（ND2NZ/NZ2ND/DN2NZ）、随路量化激活、非对齐搬运、Unified Buffer（UB）内部搬运（Copy）、矩阵分形搬运（LoadData（2D矩阵搬运）/LoadData（卷积数据搬运））、多维数据搬运NDDMA等功能的概念与适用场景。</p></li><li><p><strong>关键参数概念：</strong> DataBlock、blockLen、blockCount、srcStride/dstStride、repeat等参数的物理含义与配置方式。</p></li><li><p><strong>通用约束：</strong> 所有数据搬运接口共性的地址对齐要求、数据量约束、同步规则等。</p></li><li><p><strong><a href="data_move_concept.html">数据搬运概念</a></strong></p></li><li><p><strong><a href="data_path.html">数据通路</a></strong></p></li><li><p><strong><a href="overall_constraints.html">总体约束说明</a></strong></p></li></ul></article></div>',1)])])}const I=t(r,[["render",s]]);export{v as __pageData,I as default};
